import{_ as a,C as i,o as l,c as h,ak as r,E as o,j as d,a as c}from"./chunks/framework.DxrHb2fb.js";const x=JSON.parse('{"title":"PieChart 饼图","description":"","frontmatter":{},"headers":[],"relativePath":"components/pie-chart.md","filePath":"components/pie-chart.md","lastUpdated":1790454556000}'),n={name:"components/pie-chart.md"};function s(p,t,u,b,g,m){const e=i("XhDemo");return l(),h("div",null,[t[0]||(t[0]=r('<h1 id="piechart-饼图" tabindex="-1">PieChart 饼图 <a class="header-anchor" href="#piechart-饼图" aria-label="Permalink to &quot;PieChart 饼图&quot;">​</a></h1><p>一眼看出少量类目在整体中的占比。缺省画成环形，中心显示合计；也可以画成实心饼、上半环或按数值画半径的玫瑰图。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/pie-chart" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/pie-chart.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/pie-chart" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/pie-chart" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/pie-chart.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>一行数据一个扇区：nameField 取扇区名字段，valueField 取数值字段；缺省画成环形，中心显示合计</p>',5)),o(e,{src:"pie-chart/01-basic"}),t[1]||(t[1]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;pie-chart&quot;</code>：<strong><code>root</code></strong> · <code>caption</code> · <code>legend</code> · <code>legend-item</code> · <code>legend-swatch</code> · <code>legend-label</code> · <strong><code>viewport</code></strong> · <strong><code>plot</code></strong> · <code>slice</code> · <code>leader-line</code> · <code>slice-label</code> · <code>focus-ring</code> · <code>center</code> · <code>center-value</code> · <code>center-label</code> · <code>tooltip</code> · <code>tooltip-header</code> · <code>tooltip-row</code> · <code>tooltip-swatch</code> · <code>tooltip-value</code> · <code>tooltip-name</code> · <code>empty</code> · <code>summary</code> · <code>table</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="实心饼" tabindex="-1">实心饼 <a class="header-anchor" href="#实心饼" aria-label="Permalink to &quot;实心饼&quot;">​</a></h3><p>variant=&quot;pie&quot; 去掉中心的空洞；扇区装得下时把占比写在扇区里</p>',6)),o(e,{src:"pie-chart/02-pie"}),t[2]||(t[2]=d("h3",{id:"自定义中心",tabindex:"-1"},[c("自定义中心 "),d("a",{class:"header-anchor",href:"#自定义中心","aria-label":'Permalink to "自定义中心"'},"​")],-1)),t[3]||(t[3]=d("p",null,"center 插槽替换环形中心的缺省合计：这里写出结论，而不是再放一个数字",-1)),o(e,{src:"pie-chart/03-center"}),t[4]||(t[4]=d("h3",{id:"玫瑰图",tabindex:"-1"},[c("玫瑰图 "),d("a",{class:"header-anchor",href:"#玫瑰图","aria-label":'Permalink to "玫瑰图"'},"​")],-1)),t[5]||(t[5]=d("p",null,"rose 让角度均分、半径按数值：面积与数值成正比，适合各项差距悬殊时拉开层次",-1)),o(e,{src:"pie-chart/04-rose"}),t[6]||(t[6]=d("h3",{id:"半环",tabindex:"-1"},[c("半环 "),d("a",{class:"header-anchor",href:"#半环","aria-label":'Permalink to "半环"'},"​")],-1)),t[7]||(t[7]=d("p",null,'sweep="half" 自 9 点扫到 3 点，高度只要一半，适合放在指标卡上方',-1)),o(e,{src:"pie-chart/05-half"}),t[8]||(t[8]=d("h3",{id:"「其他」合并",tabindex:"-1"},[c("「其他」合并 "),d("a",{class:"header-anchor",href:"#「其他」合并","aria-label":'Permalink to "「其他」合并"'},"​")],-1)),t[9]||(t[9]=d("p",null,"扇区多于 maxSlices 时最小的几块并成「其他」，排在最后、取中性色，提示框里列出被合并的各项",-1)),o(e,{src:"pie-chart/06-other"}),t[10]||(t[10]=d("h3",{id:"数据更新",tabindex:"-1"},[c("数据更新 "),d("a",{class:"header-anchor",href:"#数据更新","aria-label":'Permalink to "数据更新"'},"​")],-1)),t[11]||(t[11]=d("p",null,"换一组数据时扇区从当前角度走到新角度；关掉动画后直接画终态",-1)),o(e,{src:"pie-chart/07-transition"}),t[12]||(t[12]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>整体由少数几部分构成，读者要看的是「哪一块大、大约占多少」：渠道构成、预算分配、问卷选项占比。</li><li>部分之和有意义，并且就是读者关心的那个整体。</li><li>与柱状图或表格并排，给出同一组数据的构成视角。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>类目多于 6 个：改用<a href="./cartesian-chart">直角坐标图</a>的横向条形图，长度比角度容易比较。</li><li>要比较几个相近的数值（如 23% 与 25%）：角度差异难以分辨，改用条形图。</li><li>只有 2 个类目：使用<a href="./statistic">统计数值</a>或<a href="./progress">进度条</a>，一个百分比就够了。</li><li>数值有正有负，或部分之和不是一个有意义的整体：占比无从谈起。</li><li>看构成随时间的变化：使用直角坐标图的百分比堆叠面积，一串饼图读不出趋势。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>数据是对象数组，每行一个扇区：<code>nameField</code> 指定扇区名所在的字段，<code>valueField</code> 指定数值所在的字段。数值为负时报错并在根上写 <code>data-state=&quot;error&quot;</code>；全部为 0 或全部隐藏时显示空态。</li><li>形态由 <code>variant</code> 切换：<code>donut</code> 环形（缺省），内半径是外半径的 0.6，中心显示可见扇区的合计；<code>pie</code> 实心饼，没有中心。</li><li>扇区缺省按数值从大到小排列，自 12 点方向顺时针；<code>sort=&quot;none&quot;</code> 按数据次序。读者从 12 点开始顺时针读，最大的一块在最前面最容易比较。</li><li>超过 <code>maxSlices</code>（缺省 6，含「其他」）时，最小的几块并成「其他」，排在最后、取中性色；提示框里列出被合并的各项。只并入一项时不合并，保留它本身。</li><li>颜色按数据次序依次取分类色 1–8；次序变化（改 <code>sort</code>、隐藏扇区）不改变颜色，同一个类目在不同图里保持同色。</li><li><code>sweep=&quot;half&quot;</code> 画成上半环（自 9 点扫到 3 点），适合放在指标卡上方；<code>rose</code> 画成南丁格尔玫瑰图：角度均分，半径按数值的平方根，面积与数值成正比。两者可以同时使用。</li><li>扇区标签由 <code>labels</code> 控制：<code>outside</code>（缺省）画在外侧、带两段式引导线，两侧各排一列，自上而下推开避免重叠，放不下时去掉最小扇区的标签；<code>inside</code> 把占比写在扇区里，扇区装不下时不写；<code>none</code> 不画。视口太窄、外侧标签会把饼挤得太小时，外侧标签整体不画，只靠图例与提示框。</li><li>相邻扇区之间留 <code>--xh-chart-gap</code>（2px）的表面缝，靠缝区分扇区而不是靠描边；缝宽沿半径保持不变。</li><li>悬停或键盘聚焦一个扇区时，其余扇区淡出到 <code>--xh-chart-dim-alpha</code>；被指着的扇区不位移、不放大，位移会改变读者对面积的判断。</li><li>图例一个扇区一项，点击切换显隐；隐藏的扇区从合计中移除，其余扇区的占比随之重新计算。</li><li>环形中心是 HTML 叠层，缺省显示合计与说明文字（<code>translations.centerLabel</code>，缺省 Total）；悬停、键盘聚焦或联动到一个扇区时换成它的占比与名字，离开后回到合计；Vue 用 <code>center</code> 插槽、React 用 <code>renderCenter</code>、Web Components 在 center 部件里写内容，都可以替换。</li><li><code>format</code> 指定数值格式（数字格式或函数），提示框、标签、中心合计与数据表共用；占比固定写成一位小数的百分数。</li><li>多张图接到同一个受控的 <code>activeKey</code> 上时，饼图按扇区名与其他图的类目对齐：在柱状图上悬停「华东」，饼图的「华东」扇区一起指示。</li><li><code>pending</code> 表示正在重新取数：保留上一帧、整体降低不透明度并在根上写 <code>aria-busy</code>。首次取数、手里还没有扇区时，空态写 <code>translations.loadingText</code>（缺省 Loading…）并转一个圈，取完仍没有数据才写 <code>emptyText</code>。</li><li>首次出现时整圈从起始角顺着扫开，标签与引导线等扫开的边缘到了才出现，环形中心等整圈扫完再淡入，合计从 0 数上去；之后的数据变化与图例切换从当前角度插值到新角度，合计从旧值滚到新值，隐藏的扇区收拢并淡出后才移除。按数据次序排列（<code>sort=&quot;none&quot;</code>）时扇区不换位，只在原处伸缩。</li><li><code>animated={false}</code>（Web Components 写 <code>animated=&quot;false&quot;</code>）关闭过渡，数据一变直接画终态。系统开了减弱动效或容器写了 <code>data-motion=&quot;reduce&quot;</code> 时几何直接到位，只保留淡入淡出。视口尺寸变化后的重排不播过渡。</li><li>过渡的快慢由动效令牌决定，组件从绘图区的计算样式读取：入场取 <code>--xh-motion-duration-reveal</code>（缺省 640ms），数据更新与图例切换取 <code>--xh-motion-duration-morph</code>（缺省 400ms）。在图或它的容器上改写它们，例如 <code>style=&quot;--xh-motion-duration-reveal: 1s&quot;</code>，只影响这张图；入场的曲线取 <code>--xh-motion-ease-enter-strong</code>，更新取 <code>--xh-motion-ease-continuous</code>。</li><li>三个适配器的作者侧写法不同，最终 DOM 一致：Vue 与 React 不写默认内容时铺开缺省结构（标题、图例、视口与绘图区、环形中心、空态、提示框）；Web Components 侧作者写外壳（root、caption、legend、viewport 与其中空的 <code>&lt;svg&gt;</code> plot，可选 center、empty 与 tooltip），扇区、标签与图例项由元素生成进去。</li><li>Web Components 侧的数据与数值格式只走 JS property；字段名、形态、次序、<code>max-slices</code>、标签与 <code>active-key</code> 另有同名属性。宿主元素缺省是行内元素，放进 flex / grid 时要给它一个宽度。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>为图写标题：<code>caption</code> 是图的可访问名称，饼图尤其需要说明「整体」是什么。</li><li>扇区保持在 5 个以内；更多的类目交给「其他」，或者换成条形图。</li><li>需要读出准确数字时，把 <code>labels</code> 留在 <code>outside</code>，或者在旁边放一张<a href="./table">表格</a>。</li><li>环形中心写整体的合计或一个结论（如「完成 72%」），不要再放一张小图。</li><li>同一页的几张饼图要比较时，保持相同的 <code>sort</code> 与颜色次序，读者才能按位置对照。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>用 3D 饼图或把扇区拉出来强调：透视与位移都会歪曲面积。</li><li>用多张饼图表达时间变化：读者要在几张图之间来回比角度，改用堆叠面积或条形图。</li><li>占比之和不是 100% 的数据（多选题的选择率）：扇区面积没有含义。</li><li>把图例当作读取数值的唯一途径：数值要能从标签、提示框、摘要或数据表读到。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-pie-chart&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhPieChartCaption</code> <code>XhPieChartCenter</code> <code>XhPieChartEmpty</code> <code>XhPieChartLegend</code> <code>XhPieChartPlot</code> <code>XhPieChartRoot</code> <code>XhPieChartTooltip</code> <code>XhPieChartViewport</code></td></tr><tr><td>组合式函数</td><td><code>usePieChart</code></td></tr><tr><td>状态机</td><td><code>pieChartMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/pie-chart.css</code></td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>hidden-series-change</code></td><td><code>ChartHiddenSeriesChangeDetails</code></td><td>图例切换显隐；detail 为 <code>{ hiddenSeries: string[] }</code></td></tr><tr><td><code>active-key-change</code></td><td><code>ChartActiveKeyChangeDetails</code></td><td>指针或键盘换了激活的扇区；detail 为 <code>{ activeKey }</code>，收起时为 null</td></tr><tr><td><code>datum-active</code></td><td><code>ChartDatumDetails</code></td><td>悬停或聚焦到某个扇区；detail 为扇区详情，收起时为 null</td></tr><tr><td><code>datum-press</code></td><td><code>ChartDatumDetails</code></td><td>指针点击、Enter 或 Space 按在某个扇区上；detail 为扇区详情</td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhPieChartCenter</code></td><td><code>default</code></td><td><code>PieChartCenterSlotProps</code></td><td></td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>default</code></td><td><code>PieChartRootSlotProps</code></td><td>自行摆放部件；不写时铺开缺省结构：图例、视口（绘图区、环形中心与空态）、提示框。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>caption</code></td><td>—</td><td>缺省结构里的标题内容。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>center</code></td><td><code>PieChartCenterSlotProps</code></td><td>缺省结构里的环形中心内容。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>tooltip</code></td><td><code>PieChartTooltipSlotProps</code></td><td>缺省结构里的提示框内容。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>empty</code></td><td>—</td><td>缺省结构里的空态内容。</td></tr><tr><td><code>XhPieChartTooltip</code></td><td><code>default</code></td><td><code>PieChartTooltipSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhPieChartCenter</code></td><td><code>children</code></td><td><code>SlotChildren&lt;PieChartCenterSlotProps&gt;</code></td><td></td><td>替换缺省内容；函数式 children 拿到合计与激活的扇区。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>data</code></td><td><code>readonly ChartRow[]</code></td><td></td><td>数据：对象数组，每行一个扇区。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>nameField</code></td><td><code>string</code></td><td></td><td>扇区名所在的字段。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>valueField</code></td><td><code>string</code></td><td></td><td>数值所在的字段。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>variant</code></td><td><code>PieVariant</code></td><td></td><td>形态，缺省 donut。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>rose</code></td><td><code>boolean</code></td><td></td><td>南丁格尔玫瑰图：角度均分，半径按数值。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>sweep</code></td><td><code>PieSweep</code></td><td></td><td>扫过的角度，缺省 full。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>sort</code></td><td><code>PieSort</code></td><td></td><td>扇区次序，缺省 descending。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>maxSlices</code></td><td><code>number</code></td><td></td><td>最多保留几个扇区（含「其他」），缺省 6。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>labels</code></td><td><code>PieLabels</code></td><td></td><td>扇区标签，缺省 outside。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>format</code></td><td><code>NumberFormatSpec | ((value: number) =&gt; string)</code></td><td></td><td>数值格式。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>hiddenSeries</code></td><td><code>string[]</code></td><td></td><td>隐藏的扇区（受控）。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>defaultHiddenSeries</code></td><td><code>string[]</code></td><td></td><td>初始隐藏的扇区（非受控）。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>activeKey</code></td><td><code>ChartKey | null</code></td><td></td><td>激活的键（受控）：与别的图联动时是类目名。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>pending</code></td><td><code>boolean</code></td><td></td><td>数据重取中：保留上一帧、整体降低不透明度。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>animated</code></td><td><code>boolean</code></td><td></td><td>播放过渡动画，缺省 true；false 时直接画终态。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>locale</code></td><td><code>string</code></td><td></td><td></td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>translations</code></td><td><code>Partial&lt;PieChartTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>onHiddenSeriesChange</code></td><td><code>PieChartProps[&#39;onHiddenSeriesChange&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>onActiveKeyChange</code></td><td><code>PieChartProps[&#39;onActiveKeyChange&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>onDatumActive</code></td><td><code>PieChartProps[&#39;onDatumActive&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>onDatumPress</code></td><td><code>PieChartProps[&#39;onDatumPress&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>caption</code></td><td><code>ReactNode</code></td><td></td><td>缺省结构里的标题内容。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>renderCenter</code></td><td><code>(props: PieChartCenterSlotProps) =&gt; ReactNode</code></td><td></td><td>缺省结构里的环形中心内容。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>renderTooltip</code></td><td><code>(props: PieChartTooltipSlotProps) =&gt; ReactNode</code></td><td></td><td>缺省结构里的提示框内容。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>empty</code></td><td><code>ReactNode</code></td><td></td><td>缺省结构里的空态内容。</td></tr><tr><td><code>XhPieChartRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;PieChartRootSlotProps&gt;</code></td><td></td><td>自行摆放部件；不写时铺开缺省结构：图例、视口（绘图区、环形中心与空态）、提示框。</td></tr><tr><td><code>XhPieChartTooltip</code></td><td><code>children</code></td><td><code>SlotChildren&lt;PieChartTooltipSlotProps&gt;</code></td><td></td><td>替换缺省内容；函数式 children 拿到激活的扇区与缺省的内容模型。</td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;error&#39; | undefined</td></tr><tr><td><code>tooltip</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>empty</code></td><td>&#39;loading&#39; | undefined</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>model</code></td><td><code>PieModel</code></td><td>管线产物：扇区、布局、场景与无障碍模型。</td></tr><tr><td><code>scene</code></td><td><code>Scene</code></td><td>要画的场景；尚未测量时为空场景。</td></tr><tr><td><code>overlay</code></td><td><code>PieOverlay</code></td><td>前景层：焦点环画在扇区之上。</td></tr><tr><td><code>measured</code></td><td><code>boolean</code></td><td>视口尚未测量（服务端与首帧）。</td></tr><tr><td><code>empty</code></td><td><code>boolean</code></td><td>没有可画的数据（全部为 0、没有数据或全部隐藏）。</td></tr><tr><td><code>legendItems</code></td><td><code>readonly PieLegendItem[]</code></td><td></td></tr><tr><td><code>active</code></td><td><code>ChartDatumDetails | null</code></td><td>激活的扇区；没有时为 null。</td></tr><tr><td><code>tooltip</code></td><td><code>PieTooltipModel | null</code></td><td>提示框内容；收起时为 null。</td></tr><tr><td><code>center</code></td><td><code>{ readonly value: string, readonly label: string }</code></td><td>环形中心的缺省内容：可见扇区的合计与说明文字。</td></tr><tr><td><code>summary</code></td><td><code>string</code></td><td></td></tr><tr><td><code>table</code></td><td><code>TableModel</code></td><td>数据表模型：扇区名、数值、占比三列。</td></tr><tr><td><code>emptyText</code></td><td><code>string</code></td><td></td></tr><tr><td><code>tableCaption</code></td><td><code>string</code></td><td></td></tr><tr><td><code>activeKey</code></td><td><code>ChartKey | null</code></td><td></td></tr><tr><td><code>hiddenSeries</code></td><td><code>string[]</code></td><td></td></tr><tr><td><code>toggleSeries</code></td><td><code>(id: string) =&gt; void</code></td><td>切换某个扇区的显隐。</td></tr><tr><td><code>setFocusedDatum</code></td><td><code>(ref: { seriesId: string, index: number } | null) =&gt; void</code></td><td>移动键盘锚点：只改锚点，不移动 DOM 焦点，也不派发回调。</td></tr><tr><td><code>markTag</code></td><td><code>(mark: Mark) =&gt; PieMarkTag</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCaptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendItemProps</code></td><td><code>(item: PieLegendItem) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getLegendSwatchProps</code></td><td><code>(item: PieLegendItem) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendLabelProps</code></td><td><code>(item: PieLegendItem) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPlotProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getMarkProps</code></td><td><code>(mark: Mark) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCenterProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCenterValueProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCenterLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipHeaderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipRowProps</code></td><td><code>(row: PieTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipSwatchProps</code></td><td><code>(row: PieTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipValueProps</code></td><td><code>(row: PieTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipNameProps</code></td><td><code>(row: PieTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getEmptyProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSummaryProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTableProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/toolbar/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>总是</td><td>绘图区只占一个 Tab 位：焦点落到锚点扇区，首次为 12 点方向的第一个扇区；图例同样只占一个 Tab 位</td></tr><tr><td><code>ArrowRight</code> / <code>ArrowDown</code></td><td>焦点在绘图区</td><td>顺时针移到下一个扇区；已在最后一个则原地不动</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowUp</code></td><td>焦点在绘图区</td><td>逆时针移到上一个扇区</td></tr><tr><td><code>Home</code></td><td>焦点在绘图区</td><td>第一个扇区</td></tr><tr><td><code>End</code></td><td>焦点在绘图区</td><td>最后一个扇区</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在绘图区</td><td>报告聚焦的扇区（onDatumPress）</td></tr><tr><td><code>Escape</code></td><td>提示框显示着</td><td>收起提示框，焦点留在原处；按键不拦截，外层浮层的关闭仍归它自己</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowRight</code> / <code>Home</code> / <code>End</code></td><td>焦点在图例</td><td>在图例项之间移动，左右键跟随文字方向的视觉次序</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在图例项</td><td>切换该扇区的显隐（原生按钮行为）</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>legend</code></td><td><code>aria-label</code></td><td>translations.legendLabel</td></tr><tr><td><code>legend</code></td><td><code>role</code></td><td>&#39;toolbar&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>aria-pressed</code></td><td>&#39;false&#39; | &#39;true&#39;</td></tr><tr><td><code>legend-swatch</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>plot</code></td><td><code>aria-describedby</code></td><td><code>summary</code> 部件的 id</td></tr><tr><td><code>plot</code></td><td><code>aria-labelledby</code></td><td><code>caption</code> 部件的 id</td></tr><tr><td><code>plot</code></td><td><code>aria-roledescription</code></td><td>translations.chartRoleDescription</td></tr><tr><td><code>plot</code></td><td><code>role</code></td><td>&#39;graphics-document&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>mark</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><ul><li>根是 <code>&lt;figure&gt;</code>，可访问名称来自 <code>caption</code>；不放标题时在根上写 <code>aria-label</code>。</li><li>绘图区是 <code>role=&quot;graphics-document&quot;</code>，<code>aria-describedby</code> 指向组件生成的摘要；每个扇区是 <code>role=&quot;graphics-symbol&quot;</code>，名称取 <code>translations.datumLabel</code>（缺省「名字, 数值, 占比」），务必按本地语言改写。</li><li>绘图区只占一个 Tab 位，焦点落在扇区上；右键与下键顺时针走到下一个扇区，左键与上键逆时针，Home / End 到第一个与最后一个。焦点环画在扇区之外，只在键盘聚焦时出现。</li><li>引导线、扇区标签与环形中心都 <code>aria-hidden</code> 或不在可访问树中：它们的内容已在扇区的名称里；提示框同样 <code>aria-hidden</code>。</li><li>组件在根内生成一段摘要与一张数据表，视觉隐藏、对读屏可见：摘要写扇区数、合计以及最大与最小的扇区（模板是 <code>translations.summary</code>），数据表三列是扇区名、数值与占比。</li><li>图例是 <code>role=&quot;toolbar&quot;</code>，每一项是 <code>&lt;button aria-pressed&gt;</code>，按下表示扇区可见；图例整体只占一个 Tab 位。</li><li>颜色不是区分扇区的唯一线索：外侧标签写出扇区名，图例与提示框也写出名字。</li><li>过渡只改画面：扇区的名称、合计、摘要与数据表在数据变化的那一刻就按新数据更新；收场中的扇区 <code>aria-hidden</code>、不可聚焦。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/pie-chart.css</code> 使用 <code>[data-scope=&quot;pie-chart&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;error&#39; | undefined</td></tr><tr><td><code>root</code></td><td><code>data-xh-chart-part</code></td><td>&#39;root&#39;</td></tr><tr><td><code>caption</code></td><td><code>data-xh-chart-part</code></td><td>&#39;caption&#39;</td></tr><tr><td><code>legend</code></td><td><code>data-xh-chart-part</code></td><td>&#39;legend&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>legend-item</code></td><td><code>data-value</code></td><td>item.id</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-control</code></td><td>&#39;&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-profile</code></td><td>&#39;text&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-size</code></td><td>&#39;xs&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-variant</code></td><td>&#39;ghost&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-chart-part</code></td><td>&#39;legend-item&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-chart-slot</code></td><td>slotAttr(item.slot, item.other)</td></tr><tr><td><code>legend-swatch</code></td><td><code>data-xh-chart-part</code></td><td>&#39;legend-swatch&#39;</td></tr><tr><td><code>viewport</code></td><td><code>data-xh-chart-part</code></td><td>&#39;viewport&#39;</td></tr><tr><td><code>plot</code></td><td><code>data-xh-chart-part</code></td><td>&#39;plot&#39;</td></tr><tr><td><code>center</code></td><td><code>data-drawing</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>center</code></td><td><code>data-placement</code></td><td>&#39;top&#39; | undefined</td></tr><tr><td><code>tooltip</code></td><td><code>data-placement</code></td><td>&#39;top&#39; | &#39;bottom&#39;-&#39;right&#39; | &#39;left&#39; | undefined</td></tr><tr><td><code>tooltip</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip&#39;</td></tr><tr><td><code>tooltip-header</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-header&#39;</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-series-id</code></td><td>row.key</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-row&#39;</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-xh-chart-slot</code></td><td>slotAttr(row.slot, row.other)</td></tr><tr><td><code>tooltip-swatch</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-swatch&#39;</td></tr><tr><td><code>tooltip-value</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-value&#39;</td></tr><tr><td><code>tooltip-name</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-name&#39;</td></tr><tr><td><code>empty</code></td><td><code>data-state</code></td><td>&#39;loading&#39; | undefined</td></tr><tr><td><code>empty</code></td><td><code>data-xh-chart-part</code></td><td>&#39;empty&#39;</td></tr><tr><td><code>mark</code></td><td><code>data-dimmed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>mark</code></td><td><code>data-drawing</code></td><td>&#39;&#39;</td></tr><tr><td><code>mark</code></td><td><code>data-xh-chart-part</code></td><td>mark.part | undefined</td></tr><tr><td><code>mark</code></td><td><code>data-xh-chart-slot</code></td><td>slotAttr(slice.slot, slice.other) | undefined</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-pie-chart-center-gap</code></td><td><code>center</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-0_5</code></td><td>pie-chart 的 center 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-center-value-font-size</code></td><td><code>center-value</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-heading-3-size</code></td><td>pie-chart 的 center-value 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-empty-gap</code></td><td><code>empty</code></td><td><code>gap</code></td><td><code>state=loading</code></td><td><code>--xh-space-2</code></td><td>pie-chart 的 empty 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-3</code></td><td>pie-chart 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-height</code></td><td><code>viewport</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-chart-height</code></td><td>pie-chart 的 viewport 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-legend-gap</code></td><td><code>legend</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>pie-chart 的 legend 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-legend-swatch-radius</code></td><td><code>legend-swatch</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>pie-chart 的 legend-swatch 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-series-color</code></td><td><code>legend-swatch</code><br><code>slice</code><br><code>tooltip-swatch</code></td><td><code>background</code><br><code>border</code><br><code>fill</code></td><td><code>xh-chart-slot=1</code><br><code>xh-chart-slot=2</code><br><code>xh-chart-slot=3</code><br><code>xh-chart-slot=4</code><br><code>xh-chart-slot=5</code><br><code>xh-chart-slot=6</code><br><code>xh-chart-slot=7</code><br><code>xh-chart-slot=8</code></td><td><code>--xh-chart-categorical-1</code><br><code>--xh-chart-categorical-2</code><br><code>--xh-chart-categorical-3</code><br><code>--xh-chart-categorical-4</code><br><code>--xh-chart-categorical-5</code><br><code>--xh-chart-categorical-6</code><br><code>--xh-chart-categorical-7</code><br><code>--xh-chart-categorical-8</code></td><td>pie-chart 的 legend-swatch、slice、tooltip-swatch 部件 background、border、fill 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-slice-gap</code></td><td><code>root</code></td><td><code>--xh-_chart-metric-gap</code></td><td><code>default</code></td><td><code>--xh-chart-gap</code></td><td>pie-chart 的 root 部件 --xh-_chart-metric-gap 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-slice-radius</code></td><td><code>root</code></td><td><code>--xh-_chart-metric-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>pie-chart 的 root 部件 --xh-_chart-metric-radius 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-tooltip-gap</code></td><td><code>tooltip</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>pie-chart 的 tooltip 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-tooltip-px</code></td><td><code>tooltip</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-surface-pad-sm</code></td><td>pie-chart 的 tooltip 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-tooltip-py</code></td><td><code>tooltip</code></td><td><code>padding-block</code></td><td><code>default</code></td><td><code>--xh-surface-pad-sm</code></td><td>pie-chart 的 tooltip 部件 padding-block 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-tooltip-radius</code></td><td><code>tooltip</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-overlay</code></td><td>pie-chart 的 tooltip 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-tooltip-row-gap</code></td><td><code>tooltip-row</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>pie-chart 的 tooltip-row 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-tooltip-shadow</code></td><td><code>tooltip</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-material-frosted-shadow</code></td><td>pie-chart 的 tooltip 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-pie-chart-tooltip-swatch-radius</code></td><td><code>tooltip-swatch</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>pie-chart 的 tooltip-swatch 部件 border-radius 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>动效角色：状态 · 出现 · 循环（见<a href="./../design/motion#角色">动效规范</a>）。</p><p>共享关键帧 <code>xh-fade-in</code> · <code>xh-spin</code> 由 <code>family/motion.css</code> 提供，皮肤 <code>@import</code> 它，单独引入仍成立；<code>opacity</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><ul><li>绘图区不随文字方向镜像：扇区自 12 点顺时针排列，右键始终是顺时针的下一个。</li><li>图例、标题与提示框的内容随文字方向排列，图例的左右键跟随视觉次序翻转。</li></ul>',56))])}const f=a(n,[["render",s]]);export{x as __pageData,f as default};
